import sys


class TrieNode:
    __slots__ = ("children", "is_end")

    def __init__(self):
        self.children = {}
        self.is_end = False


class Trie:
    def __init__(self):
        self.root = TrieNode()

    def insert(self, word: str) -> None:
        node = self.root
        for ch in word:
            if ch not in node.children:
                node.children[ch] = TrieNode()
            node = node.children[ch]
        node.is_end = True

    def search(self, word: str) -> bool:
        node = self.root
        for ch in word:
            if ch not in node.children:
                return False
            node = node.children[ch]
        return node.is_end

    def starts_with(self, prefix: str) -> bool:
        node = self.root
        for ch in prefix:
            if ch not in node.children:
                return False
            node = node.children[ch]
        return True


def main() -> None:
    data = sys.stdin.read().splitlines()
    if not data:
        return

    try:
        n = int(data[0].strip())
    except ValueError:
        return

    trie = Trie()
    out = []

    for i in range(1, n + 1):
        if i >= len(data):
            break
        parts = data[i].split()
        if not parts:
            continue
        op = parts[0]
        if op == "insert":
            if len(parts) > 1:
                trie.insert(parts[1])
        elif op == "search":
            if len(parts) > 1:
                out.append("true" if trie.search(parts[1]) else "false")
        elif op == "startsWith":
            if len(parts) > 1:
                out.append("true" if trie.starts_with(parts[1]) else "false")

    if out:
        sys.stdout.write("\n".join(out) + "\n")


if __name__ == "__main__":
    main()
